This solution will be in Python using OOP principles:

```python
import datetime
from dateutil.relativedelta import relativedelta

class Employee:
    def __init__(self, id, name, age, salary, role, date_of_joining):
        self.id = id
        self.name = name
        self.age = age
        self.salary = salary
        self.role = role
        self.date_of_joining = datetime.datetime.strptime(date_of_joining, '%Y-%m-%d')

    def years_of_service(self):
        return relativedelta(datetime.datetime.now(), self.date_of_joining).years

class ManagementSystem:
    def __init__(self):
        self.employees = {}

    def add_employee(self, id, name, age, salary, role, date_of_joining):
        self.employees[id] = Employee(id, name, age, salary, role, date_of_joining)

    def remove_employee(self, id):
        if id in self.employees:
            del self.employees[id]

    def update_employee(self, id, name=None, age=None, salary=None, role=None, date_of_joining=None):
        if id in self.employees:
            if name:
                self.employees[id].name = name
            if age:
                self.employees[id].age = age
            if salary:
                self.employees[id].salary = salary
            if role:
                self.employees[id].role = role
            if date_of_joining:
                self.employees[id].date_of_joining = datetime.datetime.strptime(date_of_joining, '%Y-%m-%d')

class RoleBasedAccessControl:
    def __init__(self):
        self.employee_access = {
            'management': ['add', 'remove', 'update'],
            'non-management': ['view']
        }

    def access(self, role, operation):
        if operation in self.employee_access[role]:
            return True
        else:
            return False

ms = ManagementSystem()
ms.add_employee(1, 'John', 25, 50000, 'management', '2019-01-01')
ms.add_employee(2, 'Jane', 24, 60000, 'non-management', '2020-01-01')
rbac = RoleBasedAccessControl()
print(rbac.access(ms.employees[1].role, 'remove'))  # True
print(rbac.access(ms.employees[2].role, 'remove'))  # False
```
In this setup, only the management level employees have access rights to add, remove and update other employees while non-management level employees only have viewing access. Note that the way access control is performed here is quite simplistic and would likely need to be enhanced for a real world application. 

Also, the input and output of the date of joining are hardcoded to the format '%Y-%m-%d' (year-month-day). In a real world application, you may want to add error checking and handle different formats.

