```python
def normalize_to_currency(amount, from_currency, to_currency):
    conversion_rates = {
        'USD': {'USD': 1, 'EUR': 0.85, 'JPY': 110.35},
        'EUR': {'USD': 1/0.85, 'EUR': 1, 'JPY': 110.35/0.85},
        'JPY': {'USD': 1/110.35, 'EUR': 0.85/110.35, 'JPY': 1}
    }
    try:
        converted_amount = amount * conversion_rates[from_currency][to_currency]
        return '{:.2f}'.format(converted_amount)
    except KeyError:
        return 'Invalid currency. Valid options: USD, EUR, JPY'

```
