```python
class Employee(object):
    def __init__(self, job_title, years_of_experience, salary, performance_rating):
        self.job_title = job_title
        self.years_of_experience = years_of_experience
        self.salary = salary
        self.performance_rating = performance_rating

    def calculate_bonus(self):
        if self.years_of_experience > 5:
            if self.performance_rating > 8:
                return self.salary * 0.1
            else:
                return self.salary * 0.05
        else:
            if self.performance_rating > 8:
                return self.salary * 0.05
            return 0


class Manager(Employee):

    def __init__(self, job_title, years_of_experience, salary, performance_rating):
        super().__init__(job_title, years_of_experience, salary, performance_rating)
        self.direct_reports = []

    def add_employee(self, employee):
        self.direct_reports.append(employee)

    def remove_employee(self, employee):
        self.direct_reports.remove(employee)

    def calculate_total_team_salary(self):
        total = self.salary
        for report in self.direct_reports:
            total += report.salary + report.calculate_bonus()
        return total


if __name__ == "__main__":

    # create employees
    emp1 = Employee('Engineer', 3, 50000, 9)
    emp2 = Employee('Designer', 6, 60000, 8)

    # create manager
    manager = Manager('Manager', 10, 100000, 9)

    # add employees to manager's team
    manager.add_employee(emp1)
    manager.add_employee(emp2)

    # display total team salary
    print('Total team salary: ', manager.calculate_total_team_salary())
```

In the code above, there are two classes: `Employee` and `Manager`. `Manager` is derived from `Employee` since a manager is also an employee. The method `calculate_bonus` will calculate employee's yearly bonuses based on their years of experience and performance rating. The `add_employee` and `remove_employee` methods are to add and remove employees for a manager respectively. Calculating total team's salary is done by `calculate_total_team_salary` method.

