import ast
import operator as op

def evaluate_expr(expr):
    NODE_OPS = {ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul,
                ast.Div: op.truediv, ast.USub: op.neg}

    def _evaluate(node):
        if isinstance(node, ast.Num):
            return node.n
        elif isinstance(node, ast.BinOp):  
            return NODE_OPS[type(node.op)](_evaluate(node.left), _evaluate(node.right))
        elif isinstance(node, ast.UnaryOp):  
            return NODE_OPS[type(node.op)](_evaluate(node.operand))
        else:
            raise TypeError(node)

