function primeFactors($num) 
{
    // Used to store prime factors of number
    $prime_array = array();

    while ($num % 2 == 0) 
    {
        array_push($prime_array, 2);
        $num = $num / 2;
    }

    // Just to take care of odd numbers,
    // we are starting from 3
    for ($i = 3; $i <= sqrt($num); $i += 2)
    {
        // Making sure the number
        // can be divided by i
        while ($num % $i == 0) 
        {
            array_push($prime_array, $i);
            $num = $num / $i;
        }
    }

    // Check if num is a prime number
    if ($num > 2)
        array_push($prime_array, $num);

    // Print all Prime Factors
    foreach($prime_array as $prime)
        echo $prime . " ";
}

