  if (len1 < len_max) {
    vec1 <- c(vec1, rep(0, len_max - len1))
  } else if (len2 < len_max) {
    vec2 <- c(vec2, rep(0, len_max - len2))
  }

  # calculate and return the average vector
  return ((vec1 + vec2)/2)
}

