Develop a JavaScript function that converts a multi-level nested JSON object into a nested HTML table. The function should handle undefined fields gracefully, null values, empty arrays, and other complex data types such as Date and function instances. Furthermore, the function should also incorporate error handling for circular references in the JSON object. Attributes need to be sorted in a specific order in the table regardless of the order they appear in the object. JavaScript data types (strings, numbers, objects, arrays) should be visually distinguishable in the HTML table.

Arrange for your function's efficiency and performance to handle large nested data.

Start with the following JSON object:

```javascript
let json = {
 "person": {
   "name": "Peter",
   "position": null,
   "address": {
     "street": "High Street",
     "number": "10",
     "city": "London",
     "country": "UK"
   },
   "age": 25,
   "birthday": new Date("1996-05-14"),
   "printName": function() {
     console.log(this.name);
   },
   "pets": [
     {
       "name": "Rex",
       "type": "dog",
       "age": 7,
     },
     {
       "name": "Molly",
       "type": "cat",
       "age": 5,
     }
   ],
   "nicknames": [],
 }
}
```

output:
This problem can be solved by using recursive function that will iterate over every property in JSON object and creates a nested HTML table.

```javascript
function jsonToHtmlTable(json) {
    let html = '<table>';
    for (let key in json) {

        if (!json.hasOwnProperty(key)) continue; // skip if key does not belongs to json
        let value = json[key];

        // Sorting an array with nested object
        if (Array.isArray(value) && typeof value[0] === 'object') {
            value.sort((a, b) => {
                let aProp = Object.keys(a).sort()[0];
                let bProp = Object.keys(b).sort()[0];
                return a[aProp] > b[bProp] ? 1 : a[aProp] < b[bProp] ? -1 : 0;
            });
        }

        html += '<tr><td>' + key + '</td><td>';

        if (value === null) {
            html += 'null';
        } else if (value === undefined) {
            html += 'undefined';
        } else if (typeof value === 'function') {
            html += 'function';
        } else if (value instanceof Date) {
            html += 'date';
        } else if (typeof value === 'object') {
            try {
                html += Array.isArray(value) ? 'array' : 'object';
                // convert nested json to table
                html += "<pre>" + jsonToHtmlTable(value) + '</pre>';
            } catch (e) {
                html += 'Circular Reference';
            }
        } else if (typeof value === 'string') {
            html += 'string: ' + value;
        } else if (typeof value === 'number') {
            html += 'number: ' + value;
        }

        html += '</td></tr>';
    }
    html += '</table>';
    return html;
}

let json = {
    //JSON data
}

let html = jsonToHtmlTable(json);
document.getElementById('output').innerHTML = html;
```

Above function will convert any given JSON object into the nested HTML table. This function is carefully handling primitive JavaScript data types, undefined fields, null values, empty arrays, Date and function instances of JavaScript along with error handling of the circular references of JSON objects. Javascript objects and arrays are dealt carefully. It is important to note that the performance of this function may vary if the JSON object has large depth or too many properties or contains too many circular references.
