function findLeastCommonNumber(arr) {
  // create an object to hold the frequency of each number
  let freq = {};
  for(let i = 0; i < arr.length; i++) {
    if(freq[arr[i]]) {
      freq[arr[i]]++;
    } else {
      freq[arr[i]] = 1;
    }
  }

  // find the least common frequency
  let minFreq = Math.min(...Object.values(freq));

  // find the numbers with the least frequency
  let leastFreqNums = [];
  for(let num in freq) {
    if(freq[num] === minFreq) {
      leastFreqNums.push(Number(num));
    }
  }

  // if multiple least frequent numbers, return all
  if(leastFreqNums.length > 1) {
    return leastFreqNums;
  } 

  // if single least frequent number, return the number itself
  else {
    return leastFreqNums[0]; 
  }
}

