    # Create a count table to store lengths of LCS for all substrings
    dp = [[0]*(len2+1) for _ in range(len1+1)]

    for i in range(1, len1+1):
        for j in range(1, len2+1):
            if str1[i-1] == str2[j-1]:
                dp[i][j] = 1+ dp[i-1][j-1]
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    @lru_cache(maxsize=None)
    def all_lcs(i, j):
        # Return empty set if we reach the end of either string
        if i == 0 or j == 0:
            return set([""])
        elif str1[i-1] == str2[j-1]:
            # If characters match, add the character to all sequences found till now
            return set([x + str1[i-1] for x in all_lcs(i-1, j-1)])
        else: 
            # If characters do not match, combine all LCS we get from skipping a character from one of the strings
            lcs = set()
            if dp[i][j] == dp[i-1][j]: 
                lcs.update(all_lcs(i-1, j))
            if dp[i][j] == dp[i][j-1]: 
                lcs.update(all_lcs(i, j-1))
            return lcs

    return all_lcs(len1, len2)


# Test the function:
print(lcs_all('ABCBDAB', 'BDCAB'))
print(lcs_all('1234', '123'))
print(lcs_all('ABC*', 'AB*'))
print(lcs_all(' ', ' ')) 
print(lcs_all('', ''))
```

This script prints all LCS of equal maximum length for the given pair of strings. It can handle strings with special characters, numbers, whitespaces, and even empty strings.

