Here is the correct function that creates the jagged array:

```JavaScript
function isPrime(num) {
    for(let i = 2, sqrt = Math.sqrt(num); i <= sqrt; i++)
        if(num % i === 0) return false;
    return num > 1;
}

function twoDimJaggedArray() {
    let jaggedArray = [];
    let primes = Array.from({length: 100}, (_, i) => i + 1).filter(isPrime);

    for (let i = 0; i < 3; i++) {
        let size = Math.floor(Math.random() * 5) + 1;
        let subArray = [];
        for (let j = 0; j < size; j++) {
            let randomIndex = Math.floor(Math.random() * primes.length);
            subArray.push(primes[randomIndex]);
            primes.splice(randomIndex, 1);
        }
        jaggedArray.push(subArray);
    }

    return jaggedArray;
}
```
The function includes an `isPrime` function to determine if a number is prime and then filters the numbers in the range to get only prime numbers. After that, a jagged array is created by picking random unique prime numbers.

Now, let's look at an incorrect version and identify the issues.

```JavaScript
