This is a problem that requires recursive function for navigating through the arrays and objects, and assuming that the input wouldn't cause a stack overflow. Below is an example of a JavaScript solution.

```javascript
function countUnicodeChars(input) {
    const counter = {};

    function processItem(item) {
        if (item === undefined || item === null) {
            return;
        }

        if (typeof item === 'object') {
            if (Array.isArray(item)) {
                // item is an array
                for (const subItem of item) {
                    processItem(subItem);
                }
            } else {
                // item is an object
                for (const key in item) {
                    if (Object.prototype.hasOwnProperty.call(item, key)) {
                        processItem(item[key]);
                    }
                }
            }
        } else {
            // coerce item to string
            const str = String(item);
            for (const char of str) {
                const code = char.charCodeAt(0);
                if (counter[code]) {
                    counter[code]++;
                } else {
                    counter[code] = 1;
                }
            }
        }
    }

    processItem(input);

    return counter;
}
```
