import requests
import time

class WebPageReader:
    """A simple webpage reader that pauses between requests."""

    def __init__(self, pause_duration=1):
        """Initialize the reader with the pause duration."""
        self.pause_duration = pause_duration
        self.headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 6.1; Win64; x64; rv:47.0) Gecko/20100101 Firefox/47.0",
        }

    def read_url(self, url):
        """Read a URL, then pause to avoid rate limiting."""
        response = self.safe_get(url)
        if response is not None and response.status_code == 200:
            time.sleep(self.pause_duration)
            return response.text
        else:
            # You can handle potential issue here, such as invalid URLs, rate limit exceed etc.
            print(f"Failed to get {url}")

    def safe_get(self, url):
        """ Safely attempt to get the content from the url provided, handle exceptions """
        try:
            return requests.get(url, headers=self.headers)
        except requests.exceptions.RequestException as e:
            # log the exception or print to console
            print(e)

if __name__ == "__main__":
    reader = WebPageReader(1)
    print(reader.read_url("https://www.example.com"))
```

