1. 生成一個隨機的字母或數字字符。
2. 用特定比例決定生成字母或數字。 
3. 確保新生成的字符與前一個字符不同。
4. 重複1-3步驟，直到生成了希望長度的字符串。

以下是解決此問題的JavaScript代碼:

```javascript
function generateString(len, ratio) {
    var alphaChars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.toLowerCase().split('');
    var alphaCount = 0;
    var numCount = 0;
    var lastChar = '';
    var output = '';
    while(output.length < len) {
        let alphaLimit = len * (ratio[0] / (ratio[0] + ratio[1]));
        let isAlpha = (Math.random() < (ratio[0] / (ratio[0] + ratio[1])) && alphaCount < alphaLimit) || numCount >= len * (ratio[1] / (ratio[0] + ratio[1]));
        let newChar = isAlpha ? alphaChars[Math.floor(Math.random()*26)] : Math.floor(Math.random()*10).toString();
        if(newChar == lastChar) continue;
        if(isAlpha) alphaCount++;
        else numCount++;
        lastChar = newChar;
        output += newChar;
    }
    return output;
}

// 測試該函數
console.log(generateString(10, [2, 3]));
```

