```Perl
#!/usr/bin/perl
use strict;
use warnings;

sub main {
    my $file = "sample.wav";
    open(my $fh,'<:raw',$file) or die "Could not open file '$file' $!";

    while (read $fh, my $buffer, 4) {
        print(unpack("H*", $buffer), "\n"); 
