Consider this program. It generates an array with prime numbers, and then it uses these numbers to generate the pyramid.

```C++
#include<iostream>
#include<cmath>
using namespace std;

bool isPrime(int n)
{
    if(n <= 1)
        return false;
    if(n == 2)
        return true;
    if(n%2 == 0)
        return false;
    for(int i = 3; i <= sqrt(n); i += 2)
        if(n%i == 0)
            return false;
    return true;
}

int main()
{
    int height;
    cout<<"Enter height of pyramid: ";
    cin>>height;

    int numPrimes = (height * (height + 1)) / 2;
    int primes[numPrimes] = { 0 };

    // Generate primes
    int primeIndex = 0;
    int num = 2;

    while (primeIndex < numPrimes)
    {
        if(isPrime(num))
        {
            primes[primeIndex] = num;
            primeIndex++;
        }
        num++;
    }

    // Print pyramid
    primeIndex = 0;
    for(int i=0; i<height; i++)
    {
        for(int j=0; j<height-i-1; j++)
            cout << "  ";

        for(int j=0; j<2*i+1; j++)
        {
            cout << primes[primeIndex];
            primeIndex++;

            if(j < 2*i)
                cout << " ";
            else
                cout << endl;
        }
    }

    return 0;
}
```

In the isPrime() function, we use the fact that a composite number must have at least one prime divisor less than or equal to sqrt(n) to only check up to j=sqrt(n) for factors.

In main(), we first read the height of the pyramid. If height is n, then the pyramid will have (n*(n+1))/2 primes. Hence this many prime numbers are found and stored in the primes[] array. Then these prime numbers are used to print the pyramid.

