        public String toString() {
            return "Employee{" + "name=" + name + ", age=" + age + ", salary=" + salary + "}";
        }
    }

    public static void main(String[] args) {
        List<Employee> employees = new ArrayList<>();
        employees.add(new Employee("John", 25, 3000));
        employees.add(new Employee("Sarah", 22, 3500));
        employees.add(new Employee("John", 22, 2000));
        employees.add(new Employee("John", 25, 2500));
        employees.add(new Employee("Francis", 30, 4000));

        Collections.sort(employees, new Comparator<Employee>() {
            @Override
            public int compare(Employee e1, Employee e2) {
                int comparison;
                comparison = e2.name.compareTo(e1.name);
                if(comparison != 0) return comparison;

                comparison = Integer.valueOf(e2.age).compareTo(Integer.valueOf(e1.age));
                if(comparison != 0) return comparison;

                return Double.valueOf(e2.salary).compareTo(Double.valueOf(e1.salary));
            }
        });

        for (Employee emp : employees) {
            System.out.println(emp);
        }
    }
}
