Creating a class hierarchy for geometric shapes in C++ can be a large project that needs to be tested and debugged thoroughly. For the purpose of this exercise, here is a simplified version to get started.

```cpp
#include <iostream>
#include <cmath>

class Shape {
public:
    virtual ~Shape() {}

    virtual double getArea() const = 0;
    virtual double getPerimeter() const = 0;
};

class Circle : public Shape {
public:
    Circle(double radius) : radius(radius) {}

    ~Circle() {}

    double getArea() const override {
        return M_PI * radius * radius;
    }

    double getPerimeter() const override {
        return 2 * M_PI * radius;
    }

private:
    double radius;
};

class Rectangle : public Shape {
public:
    Rectangle(double width, double height) : width(width), height(height) {}

    ~Rectangle() {}

    double getArea() const override {
        return width * height;
    }

    double getPerimeter() const override {
        return 2 * (width + height);
    }

private:
    double width;
    double height;
};

class Square : public Shape {
public:
    Square(double side) : side(side) {}

    ~Square() {}

    double getArea() const override {
        return side * side;
    }

    double getPerimeter() const override {
        return 4 * side;
    }

private:
    double side;
};

int main() {
    Shape* shapes[] = {new Circle(5), new Rectangle(4, 5), new Square(3)};
    for (const auto& shape : shapes) {
        std::cout << "Area: " << shape->getArea() << std::endl;
        std::cout << "Perimeter: " << shape->getPerimeter() << std::endl;
    }

    for (const auto& shape : shapes) {
        delete shape;
    }

    return 0;
}
```
This program defines a Shape base class with two pure virtual methods, getArea and getPerimeter, that calculate the area and perimeter respectively.

The Circle, Rectangle, and Square classes are derived from the Shape base class. Each one defines a constructor that initializes the shape's dimension(s), and overrides the base class's pure virtual methods to provide their own implementations.

The main function creates an array of three shapes - a Circle, a Rectangle, and a Square - and then iterates over this array, printing out the area and perimeter of each shape. It finally deletes each object to avoid memory leaks.

