class Company:
    def __init__(self):
        self.employees = {}
        self.archived_employees = {}
        self.departments = {}

    def add_employee(self, name, experience, department, salary):
        if not isinstance(name, str) or not isinstance(experience, int) or not isinstance(department, str) or not isinstance(salary, (int, float)):
            raise TypeError("Invalid input format")
        if experience < 0 or salary < 0:
            raise ValueError("Experience and salary cannot be negative")
        self.employees[name] = {"experience": experience, "department": department, "salary": salary}

        if department in self.departments:
            self.departments[department] += salary
        else:
            self.departments[department] = salary

    def promote(self, name, new_department, raise_percent):
        if not isinstance(raise_percent, (int, float)) or raise_percent < 0:
            raise ValueError("Raise percent cannot be negative")
        if name in self.employees:
            employee = self.employees[name]
            old_department = employee["department"]
            self.departments[old_department] -= employee["salary"]
            employee["salary"] += raise_percent/100 * employee["salary"]
            employee["department"] = new_department
            if new_department in self.departments:
                self.departments[new_department] += employee["salary"]
            else:
                self.departments[new_department] = employee["salary"]
        else:
            print(f"No employee found with name {name}")

    def long_term_employees(self):
        return {name: info for name, info in self.employees.items() if info['experience']>5}

    def employee_leave(self, name):
        if name in self.employees:
            self.archived_employees[name] = self.employees.pop(name)
            self.departments[self.archived_employees[name]['department']] -= self.archived_employees[name]['salary']
        else:
            print(f"No active employee found with name {name}")

# Test cases
