        function sortTable(column) {
            const dataType = typeof tableData[0][column];
            sortDirection = !sortDirection;
            tableData = tableData.sort((a, b) => {

                switch (dataType) {
                    case 'number':
                        return sortDirection ? a[column] - b[column] : b[column] - a[column];
                    case 'string':
                        return sortDirection ? a[column].localeCompare(b[column]) : b[column].localeCompare(a[column]);
                    default:
                        return sortDirection ? a[column] - b[column] : b[column] - a[column];
                }
            });
