```javascript
function mergeArraysWithoutDuplicates(array1, array2) {
    let set = new Set();
    for(let i = 0; i < array1.length; i++) {
        set.add(array1[i]);
    }
    for(let i = 0; i < array2.length; i++) {
        set.add(array2[i]);
    }
    return Array.from(set);
}
