    public static List<Integer> convertMorseToUnits(String morseCode) {
        List<Integer> units = new ArrayList<>();

        for (char c : morseCode.toCharArray()) {
            switch (c) {
                case '-':
                    units.add(3);
                    break;
                case '.':
                    units.add(1);
                    break;
                case ' ':
                    units.add(1);
                    break;
                case '/':
                    units.add(2);
                    break;
                default:
