Here is a simple web service using Flask:

```python
from flask import Flask, jsonify, request
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)

# configure your database URI
app.config['SQLALCHEMY_DATABASE_URI'] = 'your_database_url'
db = SQLAlchemy(app)


class Note(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    content = db.Column(db.Text)


@app.route('/notes', methods=['GET'])
def get_notes():
    notes = Note.query.all()
    return jsonify({'notes': [note.content for note in notes]})


@app.route('/notes', methods=['POST'])
def create_note():
    new_note = Note(content=request.json['content'])
    db.session.add(new_note)
    db.session.commit()
    return jsonify({'message': 'note created'}), 201


@app.route('/notes/<int:note_id>', methods=['PUT'])
def update_note(note_id):
    note = Note.query.get(note_id)
    if not note:
        return jsonify({'message': 'note not found'}), 404

    note.content = request.json['content']
    db.session.commit()
    return jsonify({'message': 'note updated'})


@app.route('/notes/<int:note_id>', methods=['DELETE'])
def delete_note(note_id):
    note = Note.query.get(note_id)
    if not note:
        return jsonify({'message': 'note not found'}), 404

    db.session.delete(note)
    db.session.commit()
    return jsonify({'message': 'note deleted'})


if __name__ == '__main__':
    app.run(debug=True)

