function getCharactersAboveThreshold(str, threshold) {
    return [...str].filter(char => {
        // Check if character is not a numerical digit
        if (isNaN(char)){
            // Find ASCII value and compare to threshold
            let asciiVal = char.charCodeAt(0);
            return asciiVal > threshold;
        }
        return false;
    });
};

