Furthermore, investigate and resolve any potential performance issues and ensure smooth functioning of the app even under heavy load. As an additional challenge, a piece of poorly optimized sample code is provided‌ ‌below‌. Your job is to identify the errors, inefficient practices and improve them in your final solution.

**Sample Code**

```javascript
var httpRequest;

function getExchangeRate(baseCurrency, targetCurrency) {
  httpRequest = new XMLHttpRequest();
  if (!httpRequest) {
    console.log('Cannot create an XMLHTTP instance');
    return false;
  }
  httpRequest.onreadystatechange = handleResponse;
  httpRequest.open('GET', `https://api.exchangeratesapi.io/latest?base=${baseCurrency}`);
  httpRequest.send();

  function handleResponse() {
    if (httpRequest.readyState === XMLHttpRequest.DONE) {
      if (httpRequest.status === 200) {
        return JSON.parse(httpRequest.responseText).rates[targetCurrency];
      } else {
        console.log(`There was a problem with the request. Request returned ${httpRequest.status}`);
      }
    }
  }
}
```

Do consider and ensure:

