```java
import java.util.Random;

public class Main {

    public static void main(String[] args) {
        // Initialize a 3D array with random integers.
        int[][][] array = new int[3][4][5];

        Random rand = new Random();
        for (int k = 0; k < array.length; k++)
            for (int i = 0; i < array[k].length; i++)
                for (int j = 0; j < array[k][i].length; j++)
                    array[k][i][j] = rand.nextInt(100) + 1;

        // Print the 3D array before transposition
        System.out.println("Original 3D array:");
        print3DArray(array);

        // Transpose the 2D arrays within the 3D array
        array = transpose3DArray(array);

        // Print the 3D array after transposition
        System.out.println("\n3D array after transpose:");
        print3DArray(array);
    }

    public static int[][][] transpose3DArray(int[][][] array) {
        int[][][] transposedArray = new int[array.length][][];

        for (int k = 0; k < array.length; k++) {
            int[][] transposed = new int[array[k][0].length][array[k].length];
            for (int i = 0; i < array[k].length; i++)
                for (int j = 0; j < array[k][i].length; j++)
                    transposed[j][i] = array[k][i][j];
            transposedArray[k] = transposed;
        }

        return transposedArray;
    }

    public static void print3DArray(int[][][] array) {
        for (int k = 0; k < array.length; k++) {
            System.out.println("Matrix " + (k + 1) + ":");
            for (int i = 0; i < array[k].length; i++) {
                for (int j = 0; j < array[k][i].length; j++) {
                    System.out.print(array[k][i][j] + " ");
                }
                System.out.println();
            }
            System.out.println();
        }
    }
}
```
