Here is a simple C++ application which calculates the maximum depth of a binary tree.

```cpp
#include<bits/stdc++.h>
using namespace std;

// Define Node for the binary tree
struct Node
{
    int data;
    Node* left, *right;
    Node(int data)
    {
        this->data = data;
        this->left = this->right = NULL;
    }
};

// Function to find the maximum depth of the binary tree
int maxDepth(Node* node)
{
    if (node == NULL)
        return 0;
    else
    {
        // Compute the depth of each subtree
        int lDepth = maxDepth(node->left);
        int rDepth = maxDepth(node->right);

        // Use the larger one
        if (lDepth > rDepth)
            return(lDepth + 1);
        else return(rDepth + 1);
    }
}

// Main function
int main()
{
    Node* root = new Node(1);

    root->left = new Node(2);
    root->right = new Node(3);
    root->left->left = new Node(4);
    root->left->right = new Node(5);

    cout << "Height of tree is " << maxDepth(root);
    return 0;
}
```

This program first creates binary tree nodes each containing some data. The maxDepth function is used to calculate the max depth of the binary tree. If the node is Null/Empty it will return 0. Otherwise, it computes the depth of the left and right sub-tree and returns the max depth out of these two plus one for the root.

In the main function, we create the nodes for the binary tree and link them to form a tree. The height of the binary tree is then calculated and printed.

