            message[i] = toupper(message[i]);
        else if (isupper(message[i]))
            message[i] = tolower(message[i]);

        // Replace vowels with next letter that is two positions ahead in the English alphabet
        switch(tolower(message[i])) {
            case 'a': message[i] = 'c'; break;
            case 'e': message[i] = 'g'; break;
            case 'i': message[i] = 'k'; break;
            case 'o': message[i] = 'q'; break;
            case 'u': message[i] = 'w'; break;
            default : break;
        }
    }
    return message;
}
```

I have used `islower()` to check if a character is a lowercase letter, and `isupper()` to check if it is an uppercase letter. `tolower()` is used to convert the character to lowercase for evaluating the switch statement logic, regardless of its original case.

When it encounters a vowel, it is replaced with a letter that lies two positions ahead in the English alphabet.

Here's how you can create such a Python decorator:

```python
def enforce_type_hinting(func):
    from functools import wraps
    import inspect

    # Get the argument annotations of the original function
    arg_annotations = inspect.getfullargspec(func).annotations

    @wraps(func)
    def wrapper(*args, **kwargs):
        # Checking that the function is called with correct positional arguments
        if len(arg_annotations) != len(args):
            raise TypeError("The number of arguments does not match the function specification.")

        # Check the types of positional arguments
        for (arg, annotation), value in zip(arg_annotations.items(), args):
            if type(value) is not annotation:
                raise TypeError(f"The argument '{arg}' is not of the expected type {annotation}.")

        # Check the types of keyword arguments
        for arg, value in kwargs.items():
            if arg in arg_annotations and not isinstance(value, arg_annotations[arg]):
                raise TypeError(f"The argument '{arg}' is not of the expected type {arg_annotations[arg]}.")

        result = func(*args, **kwargs)

        # Check the type of the result
        result_annotation = inspect.signature(func).return_annotation
        if result_annotation is not inspect._empty and not isinstance(result, result_annotation):
            raise TypeError(f"The return value is not of the expected type {result_annotation}.")

        return result

    return wrapper


# Now here is a demonstration of the decorator
@enforce_type_hinting
def complex_number_func(numbers: tuple[float, float]) -> complex:
    return complex(*numbers)


# Testing the decorated function
try:
    print(complex_number_func((3.0, 4.0)))  # This will pass
    print(complex_number_func((3, 4)))  # This will raise a TypeError
    print(complex_number_func("Hello"))  # This will raise a TypeError
except TypeError as e:
    print(e)
```

This decorator `enforce_type_hinting` wraps around a function and ensures that the argument types and the return type match the type hints that are given in the function annotation. If the types don't match, a `TypeError` is raised. Note that this decorator currently only enforces the types of positional arguments and return value but can be extended to enforce keyword argument types and even to enforce that the correct number of arguments are passed.

