public class Main {
    public static void main(String[] args) {
        Integer[] numbers = {2, 9, 6, 5, 12, 17, 10};
        int nth = 3;

        try {
            int nthMaxNumber = findNthMaxNumber(numbers, nth);
            System.out.println("The " + nth + "th max number is: " + nthMaxNumber);
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
