    static int findNthMaxNumber(Integer[] numbers, int nth) throws Exception {
        if (numbers.length == 0)
            throw new Exception("The array is empty!");
        if (nth > numbers.length)
            throw new Exception("The 'n' is greater than the size of the array!");
        if (nth <= 0)
            throw new Exception("The 'n' should be greater than 0!");

        Arrays.sort(numbers, Collections.reverseOrder());

        return numbers[nth - 1];
    }
}
