import java.util.HashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    public static void main(String[] args) {
            String input = "Java is Fun!";
            System.out.println(replaceVowels(input));
    }

    private static String replaceVowels(String input) {
            Map<Character, Character> vowelReplacementMap = new HashMap<>();
            vowelReplacementMap.put('a', 'e');
            vowelReplacementMap.put('e', 'i');
            vowelReplacementMap.put('i', 'o');
            vowelReplacementMap.put('o', 'u');
            vowelReplacementMap.put('u', 'a');
            vowelReplacementMap.put('A', 'E');
            vowelReplacementMap.put('E', 'I');
            vowelReplacementMap.put('I', 'O');
            vowelReplacementMap.put('O', 'U');
            vowelReplacementMap.put('U', 'A');

            Pattern vowelPattern = Pattern.compile("[aeiouAEIOU]");
            Matcher vowelMatcher = vowelPattern.matcher(input);
            StringBuffer resultString = new StringBuffer();

            while (vowelMatcher.find()) {
                vowelMatcher.appendReplacement(resultString, vowelReplacementMap.get(input.charAt(vowelMatcher.start())).toString());
            }
            vowelMatcher.appendTail(resultString);
            return resultString.toString();
    }
}
```

In this Java program, we first create a map of replacement vowels for every vowel. Then, we use a regular expression to match the vowels in the input string. For each match found, we replace it with the corresponding next vowel in the sequence. We apply 'appendReplacement' on each match, then at the end 'appendTail' is used to append the remaining input to the resulting string. 

When we run this program with the input string "Java is Fun!", it will replace the vowels and output "Jevi is Fen!".

