using namespace std;

int main () 
{ 
   int n = 50;
   unsigned long long f[n+1]; 

   f[0]=0; 
   f[1]=1; 

   for (int i=2; i <= n; i++) 
   { 
      f[i] = f[i-1] + f[i-2]; 
