```matlab
function [C] = sumVec(A, B)
% sumVec: this function adds two vectors would ignoring NaN values.
% Inputs
% A: input vector 1
% B: input vector 2
% Outputs
% C: output vector

% take the length of the longer vector
len = max([length(A), length(B)]);

% append zeros if the vectors do not have the same length
if length(A) < len
    A(end+1:len) = 0;
elseif length(B) < len
    B(end+1:len) = 0;
end

% add corresponding elements in vectors A and B
% replace NaN with 0 before adding
C = zeros(1,len);
for i = 1:len
    if isnan(A(i))
        A(i) = 0;
    end
    if isnan(B(i))
        B(i) = 0;
    end
    C(i) = A(i) + B(i);
end
end
```

