```python
def game_loop(player, enemies, items):
    while True:
        print(f"Player: {player.name}, Health: {player.health}")
        print("Enemies:")
        for enemy in enemies:
            print(f"{enemy.name}, Health: {enemy.health}")

        action = input("What do you want to do? (attack, use item): ")

