    for(int i = 0; i < size; i++){
        for(int j = i+1; j < size; j++){
            if(unsorted_arr[i] > unsorted_arr[j]){
                int temp = unsorted_arr[i];
                unsorted_arr[i] = unsorted_arr[j];
                unsorted_arr[j] = temp;
