Here is some simple C++ code that calculates the aggregate value of the longest consecutive subsequence in a provided array of non-negative integers:

```c++
#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

long long getLongestConsecutiveSubsequenceValue(const vector<int>& arr) {
    int size = arr.size();
    // Edge case
    if (size == 0) return 0;

    long long ans = arr[0]; 
    long long cur_sum = arr[0];

    for (int i = 1; i < size; i++) { 
        // If current number is greater than previous, 
        // add it to the current sum 
        if (arr[i] > arr[i - 1]) {
            cur_sum = cur_sum + arr[i]; 
        } 

        // If current number is equal or less, 
        // reset the current sum 
        else {
            cur_sum = arr[i]; 
        }

        // Update result 
        ans = max(ans, cur_sum); 
    }

    return ans;
}

int main() {
    vector<int> arr = {10, 5, 7, 8, 9, 1, 12, 6, 11, 10};
    cout << "The max aggregate value is: " << getLongestConsecutiveSubsequenceValue(arr) << endl;
    return 0;
}
```

This program computes the aggregate value of the longest increasing subsequence. We see that the maximum aggregated subsection from the array provided in the main function is `{5, 7, 8, 9}`, which amounts to `29`.

This coding structure should be able to manage substantial arrays with up to 10^6 elements due to its O(n) time complexity, where n represents the length of the array. This ensures high performance even for large inputs. The code might need further optimization(such as chunking the array and processing these chunks in different threads), for instance, if memory limitations are severer. However, that goes beyond the given problem scope mentioning multi-threading.

在C++中，我們可以使用`std::string::find`函數來查找指定的子字符串。下面是一個解決此問題的簡單程序：

```C++
#include <iostream>
#include <string>

std::pair<int, int> findUTF8Substring(const std::string& str, const std::string& substr)
{
    int position = -1;
    int count = 0;

    int pos = str.find(substr, 0); // 初始化位置在字符串的起始處
    while(pos != std::string::npos)
    {
        if(position == -1) position = pos; // 紀錄首次找到的位置
        count++;
        pos = str.find(substr, pos+substr.size()); // 更新位置
    }

    return std::make_pair(position, count);
}

int main() {
    std::string str = "這是一個字串";
    std::string substr = "字串";

    std::pair<int, int> result = findUTF8Substring(str, substr);
    std::cout << "子字串首次出現的位置: " << result.first 
              << ", 頻次: " << result.second << std::endl;

    return 0;
}
```
