Here is a JavaScript function named `rearrangeArray` that accomplishes your task:

```javascript
function rearrangeArray(numbers) {
    // First, sort the array in ascending order
    numbers.sort((a, b) => a - b);

    // Calculate the middle index of the array
    let medianIndex = Math.floor(numbers.length / 2);

    // Separate the array into two halves
    let firstHalf = numbers.slice(0, medianIndex);
    let secondHalf = numbers.slice(medianIndex);

    // Reverse the second half of the array for descending order
    secondHalf.reverse();

    // Concatenate the two halves around the median
    let rearrangedArray = firstHalf.concat(secondHalf);

    return rearrangedArray;
}

let numbers = [1,9,8,3,4,7,2,6,5];
