Here is a simple C++ code that generates a Fibonacci series up to the nth place. It uses exception handling for negative input values and calculates execution time for the Fibonacci series generation process:

```c++
#include <iostream>
#include <chrono>

// Define Fibonacci function
int fibonacci(int n) 
{
    if(n <= 0)
    {
        // Throw exception if the entered number is negative or 0
        throw "Invalid input. Input value should be a positive integer.";
    }
    else if (n == 1)
        return 0;
    else if (n == 2)
        return 1;
    else
    {
        int first = 0, second = 1, next;
        for(int i = 3; i <= n; i++)
        {
            next = first + second;
            first = second;
            second = next;
        }
        return next;
    }
    return 0;
}

// Define main function
int main() 
{
    int n;
    std::cout << "Enter the value of n: ";
    std::cin >> n;

    try
    {
        // Start timer
        auto start = std::chrono::high_resolution_clock::now();

        // Call Fibonacci function and print Fibonacci series
        std::cout << "Fibonacci series up to " << n << " place:\n";
        for(int i = 1; i <= n; i++)
        {
            std::cout << fibonacci(i) << " ";
        }

        // End timer and calculate duration
        auto end = std::chrono::high_resolution_clock::now();
        double time_taken = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
        time_taken *= 1e-9;

        // Print time taken
        std::cout << "\nTime taken by program is : " << std::fixed << time_taken << " sec" << std::endl;
    }
    catch(const char* msg)
    {
        std::cout << msg << std::endl;
    }

    return 0;
}
```

This basic iterative algorithm has a time complexity of O(n). Each number in the series is calculated from the sum of the two preceding ones. The calculation time increases linearly with the size of the input. It used built-in chrono library of C++ to calculate time taken in seconds. 

