function transform(characters, i){
    if (characters[i]) {
        return transform(characters, ++i);
    }
    return characters[--i] ? characters[i].toUpperCase() : '';
}

function reverseWords(sentenceArr, i){
    let nextIndex = sentenceArr.indexOf(" ", i);
    nextIndex = nextIndex > -1 ? nextIndex : sentenceArr.length;

    let reversedWord = '';
    for(let j = nextIndex - 1; j >= i; j--){
        reversedWord += transform(sentenceArr[j].split(''), 0);
    }

