            username.charCodeAt(i) + 
            (username.charCodeAt(i+1) || 0) + 
            (username.charCodeAt(i+2) || 0)
        );
    }
    displayPassword(password);
}

function displayPassword(password) {
    // Create a paragraph to display the generated password
    const passwordP = document.createElement("P");
    passwordP.innerText = "Generated Password: " + password;
    document.getElementById('myForm').appendChild(passwordP);
}
```

