const rotateArrayToRight = (arr, times) => {
  for (let i = 0; i < times; i++) {
    arr.unshift(arr.pop());
  }
  return arr;
};


const isSectionSorted = (arr, startIndex, endIndex, isPositiveSection) => {
  for (let i = startIndex; i < endIndex; i++) {
    if (isPositiveSection && arr[i] < 0) {
      return false;
    }
    if (!isPositiveSection && arr[i] > 0) {
      return false;
    }
  }
  return true;
};
