In JavaScript, you can create a class using constructor function and the prototype property. Here's an example how your request could be implemented:

```javascript
// Define class Point
function Point(x, y, z) {
  this.x = x;
  this.y = y;
  this.z = z;
}

// Method for calculate distance between two points
Point.prototype.distanceTo = function(other) {
  const dx = this.x - other.x;
  const dy = this.y - other.y;
  const dz = this.z - other.z;
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
};

// Method to add two points (vectors)
Point.prototype.add = function(other) {
  return new Point(this.x + other.x, this.y + other.y, this.z + other.z);
};

// Method to subtract two points (vectors)
Point.prototype.subtract = function(other) {
  return new Point(this.x - other.x, this.y - other.y, this.z - other.z);
};

// Method to scale a point (vector)
Point.prototype.scale = function(scalar) {
  return new Point(this.x * scalar, this.y * scalar, this.z * scalar);
};

// Method to calculate angle between three points
// Return value is in degrees
Point.angleBetween = function(A, O, B) {
  const vector_OA = A.subtract(O);
  const vector_OB = B.subtract(O);

  const dotProduct = vector_OA.x * vector_OB.x + vector_OA.y * vector_OB.y + vector_OA.z * vector_OB.z;
  const magnitudeProduct = vector_OA.distanceTo(new Point(0,0,0)) * vector_OB.distanceTo(new Point(0,0,0));

  // Handle edge case of zero-length vectors
  if(magnitudeProduct === 0) return 0;

  let angle = Math.acos(dotProduct / magnitudeProduct); // in radian
  return angle * (180 / Math.PI); // convert to degrees
};
```
