Here's a design using java code:

```java
import java.util.HashSet;

public class Student {
    String fullName;
    String uid;
    int graduationYear;
    double gpa;

    static HashSet<String> set = new HashSet<>(); //to Check for unique uid

    public Student(String fullName, String uid, int graduationYear, double gpa) throws Exception {
        if (gpa < 0 || gpa > 4) {
            throw new Exception("Invalid GPA. It should be between 0 and 4.");
        }
        if (set.contains(uid)) {
            throw new Exception("UID already exists.");
        }
        this.fullName = fullName;
        this.uid = uid;
        this.graduationYear = graduationYear;
        this.gpa = gpa;
        set.add(uid);
    }
}

class Instructor {
    private String name;
    private String id;

    public Instructor(String name, String id) {
        this.name = name;
        this.id = id;
    }

    // Getters and setters
}

class Course {
    private String name;
    private String code;
    private Instructor instructor;

    public Course(String name, String code, Instructor instructor) {
        this.name = name;
        this.code = code;
        this.instructor = instructor;
    }

    // Getters and setters
}
```

