Below is a simple C++ code using for loops and the bubble sorting algorithm to sort the array in both ascending and descending order.

```cpp
#include <iostream>
using namespace std;

void swap(int &a, int &b) 
{
    int temp = a;
    a = b;
    b = temp;
}

void bubbleSort(int arr[], int n, bool ascending=true) 
{
    for(int i=0; i<n-1; i++) 
    {
        for(int j=0; j<n-i-1; j++)
        {
            if(ascending) 
            {
                if(arr[j] > arr[j+1]) 
                {
                    swap(arr[j], arr[j+1]);
                }
            }
            else 
            {
                if(arr[j] < arr[j+1]) 
                {
                    swap(arr[j], arr[j+1]);
                }
            }
        }
    }
}

void printArray(int arr[], int size) 
{
    for (int i=0; i<size; i++)
        cout << arr[i] << " ";
    cout << endl;
}

int main() 
{
    int arr[] = {2, 3, 1, 5, 4};
    int size = sizeof(arr)/sizeof(arr[0]);

    cout << "Original array: \n";
    printArray(arr, size);

    bubbleSort(arr, size);
    cout << "\nSorted array in ascending order: \n";
    printArray(arr, size);

    bubbleSort(arr, size, false);
    cout << "\nSorted array in descending order: \n";
    printArray(arr, size);

    return 0;
}
```

In the above code, `swap()` function is used to swap two elements. `bubbleSort()` function implements the bubble sort algorithm. It has third optional boolean parameter to decide whether sorting is in ascending order (if its value is `true`) or in descending order (if its value is `false`). `printArray()` function is used to print the array element. Finally, in the `main()` function, array is defined, sorted in both ways and then printed.

