```jsx
import React, { Component } from 'react';
import { BrowserRouter as Router, Route, Link } from 'react-router-dom';

class BookList extends Component {
  render() {
    const books = [
        { id: 1, title: "Harry Potter and the Sorcerer's stone", author: "J.K. Rowling" },
        { id: 2, title: "The Lord of The Rings", author: "J.R.R. Tolkien" },
        { id: 3, title: "To Kill a Mockingbird", author: "Harper Lee" }
    ];

    return (
      <div>
        {books.map((book, index) => (
          <div key={index}>
            <Link to={`/book/${book.id}`}>{book.title}</Link>
          </div>
        ))}
      </div>
    );
  }
}

class BookDetail extends Component {
  render() {
    const { match } = this.props;
    const bookId = match.params.id; // get the book id from the route params

    const books = [
        { id: 1, title: "Harry Potter and the Sorcerer's stone", author: "J.K. Rowling", description: "This is the story of a boy who discovers he is a wizard." },
        { id: 2, title: "The Lord of The Rings", author: "J.R.R. Tolkien", description: "A fantasy epic of the struggle between good and evil in Middle-Earth." },
        { id: 3, title: "To Kill a Mockingbird", author: "Harper Lee", description: "A powerful story that explores racial injustice in a small Southern town." }
    ];

    // Find the book by its id
    const book = books.find(b => b.id == bookId);

    return (
      <div>
        <h1>{book.title}</h1>
        <h2>{book.author}</h2>
        <p>{book.description}</p>
        <Link to="/">Back to book list</Link>
      </div>
    );
  }
}

function App() {
  return (
    <Router>
      <Route exact path="/" component={BookList} />
      <Route path="/book/:id" component={BookDetail} />
    </Router>
  );
}

export default App;
```

