    .then(function(response) {
        console.log(response);
    })
    .catch(function(error) {
        console.log(error);
    });
```
You can use a package like `axios-cookiejar-support` to add cookie support to Axios if the website relies on cookies for sessions. 

```javascript
const axios = require('axios').default;
