axios
    .post('API_URL', {
        username: 'YOUR_USERNAME',
        password: 'YOUR_PASSWORD'
    }, {
        jar: cookieJar, // tough.CookieJar or boolean
        withCredentials: true, // If true, send cookie stored in jar
    })
