In C++, the problem of removing a node from a doubly linked list at a specific index can be effectively solved by defining a `Node` structure and a `DoublyLinkedList` class. This doubly linked list class will contain a `head` and `tail` pointer and a `RemoveAt` function. 

The `RemoveAt` function would traverse the list until it gets to the node at the desired index and then manipulate the `previous` and `next` pointers of the surrounding nodes to fully detach and remove the node. Please note that the index starts from 0.

Here is the C++ code which demonstrates the above solution:

```cpp
#include<iostream>
using namespace std;

// Defining the structure for node of doubly linked list
struct Node {
    int data;
    Node* next;
    Node* prev;
};

// Defining the doubly linked list class
class DoublyLinkedList {
    private:
        Node* head;
        Node* tail;
    public:
        DoublyLinkedList() {
            head = NULL;
            tail = NULL;
        }

        void AddEnd(int data) {
            Node* newNode = new Node();
            newNode->data = data;
            newNode->next = NULL;
            newNode->prev = tail;

            if (head == NULL) {
                head = newNode;
                tail = newNode;
            } else {
                tail->next = newNode;
                tail = newNode;
            }
        }

        void RemoveAt(int index) {
            if (head == NULL) {
                // If list is empty, do nothing
                return;
            }

            Node* temp = head;
            int idx = 0;
            while(temp != NULL && idx != index) {
                temp = temp->next;
                idx++;
            }

            // If the node is found
            if (temp != NULL) {
                // If node is at head
                if (temp == head) {
                    head = head->next;
                    head->prev = NULL;
                }
                // If node is at tail
                else if (temp == tail) {
                    tail = tail->prev;
                    tail->next = NULL;
                }
                // If node is in the middle
                else {
                    temp->prev->next = temp->next;
                    temp->next->prev = temp->prev;
                }
                delete temp; // To finally delete the node
            } else {
                cout << "Please enter valid index." << endl;
            }
        }

        void Display() {
            Node* temp = head;
            while(temp != NULL) {
                cout << temp->data << " ";
                temp = temp->next;
            }
            cout << endl;
        }
};
```
To delete the node at third place, we would use the following implementation.
```cpp
int main() {
    DoublyLinkedList dll;
    dll.AddEnd(84);
    dll.AddEnd(13);
    dll.AddEnd(25);
    dll.AddEnd(48);
    dll.AddEnd(50);

    cout << "Initial List: ";
    dll.Display();

    int index = 2; // Index for the node to be removed. index starts from 0.
    dll.RemoveAt(index);

    cout << "List after removing node at index " << index << ": ";
    dll.Display();

    return 0;
}
```
Remember, in most of the programming languages, the index starts from 0, so if we consider the node at third place, its index will be 2.

