Here's an approach using Python. In this solution, we will first define Node and DoublyLinkedList classes. The Node class will have a constructor to initialize node data and links to previous and next nodes. DoublyLinkedList class will have methods to add nodes at the end of the list ('append'), delete nodes based on data value ('delete_nodes') and print the list ('print_list').

```python
class Node:
    def __init__(self, data=None):
        self.data = data
        self.next = None
        self.prev = None


class DoublyLinkedList:
    def __init__(self):
        self.head = None

    def append(self, data):
        if not self.head:
            self.head = Node(data)
        else:
            new_node = Node(data)
            temp = self.head
            while temp.next:
                temp = temp.next
            temp.next = new_node
            new_node.prev = temp

    def delete_nodes(self, data):
        temp = self.head
        while temp:
            if temp.data == data:
                if temp.prev:
                    temp.prev.next = temp.next
                if temp.next:
                    temp.next.prev = temp.prev

                if temp == self.head:
                    self.head = temp.next

            temp = temp.next

    def print_list(self):
        temp = self.head
        while temp:
            print(temp.data, end=' ')
            temp = temp.next
        print()


# Example usage
dll = DoublyLinkedList()
dll.append(5)
dll.append(6)
dll.append(7)
dll.append(7)
dll.append(8)

dll.print_list()  # 5 6 7 7 8
dll.delete_nodes(7)
dll.print_list()  # 5 6 8
```
In this implementation, deleting nodes from the list has linear time complexity (O(n)) because we traverse the list only once and deletion operation given a pointer to the node is constant time. Therefore, it satisfies the requirement of better than O(n²) time complexity.

Also, this function successfully handles the mentioned conditions because it doesn't assume the list or the next/previous nodes to always exist (therefore it can handle empty lists or node deletions from list boundaries), and it's able to delete multiple nodes with the same data value.

Here is a simple implementation of this problem with test cases:

```java
public class Node {
    int data;
    Node next;

    Node(int data) {
        this.data = data;
        next = null;
    }
}

public class LinkedList {
    Node head;

    public void insert(int data, int position) {
        Node newNode = new Node(data);

        if(position == 0) {
            newNode.next = head;
            head = newNode;
        } else {
            Node current = head;
            for(int i=0; i<position-1; i++) {
                if(current.next == null)
                    throw new IllegalArgumentException("Position greater than list size");
                current = current.next;
            }
            newNode.next = current.next;
            current.next = newNode;
        }
    }

    public void delete(int value) {
        if(head == null) return;

        if(head.data == value) {
            head = head.next;
            return;
        }

        Node current = head;

        while(current.next != null) {
            if(current.next.data == value) {
                current.next = current.next.next;
                return;
            }
            current = current.next;
        }
    }

    public Node search(int value) {
        Node current = head;
        while(current != null) {
            if(current.data == value)
                return current;
            current = current.next;
        }
        return null;
    }

    public void reverse() {
        Node prev = null;
        Node current = head;
        Node next = null;

        while(current != null) {
            next = current.next;
            current.next = prev;
            prev = current;
            current = next;
        }

        head = prev;
    }
}

public class LinkedListTest {
    public static void main(String[] args) {
        LinkedList list = new LinkedList();

        // Test insert
        list.insert(1,0);
        list.insert(2,1);
        list.insert(3,2);

        // Test delete
        list.delete(2);

        // Test search
        assert list.search(3) != null;
        assert list.search(2) == null;

        // Test reverse
        list.reverse();
        assert list.head.data == 3;
        assert list.head.next.data == 1;
    }
}
```

This program defines a linked list and related operations in Java. The example includes insert, delete, search and reverse methods. The insert method inserts a new node at a specified position, the delete method deletes nodes based on value, the search method searches a node based on value, and the reverse method reverse the linked list. The `LinkedListTest` class is utilized to test all the methods for correctness.

