import unittest

class TestBook(unittest.TestCase):
    def test_fetch_and_validate(self):
        book = Book('Charlie and the Chocolate Factory', 'Roald Dahl')
        book.fetch_details()
        self.assertTrue(book.validate_isbn())

if __name__ == '__main__':
    unittest.main()
```
