```python
def bubble_sort(list):
    for i in range(len(list)):
        for j in range(len(list)-i-1):
            if list[j] > list[j+1]:
                list[j], list[j+1] = list[j+1], list[j]  
    return list

def anagram(str1, str2): 
    n1 = len(str1) 
    n2 = len(str2)

    if n1 != n2: 
        return False

    str1 = bubble_sort(list(str1)) 
    str2 = bubble_sort(list(str2))

    for i in range(0, n1): 
        if str1[i] != str2[i]: 
            return False

    return True

