    string forename;
    string surname;
    int *academic_grades;

  //Default constructor
  Scholar() {
    forename = " ";
    surname = " ";
    academic_grades[0] = 0;
  }

  void addGrade(int grade) {
    int size = sizeof(academic_grades) / sizeof(academic_grades[0]);
    academic_grades[size + 1] = grade;
  }
