```cpp
#include<iostream>
#include<vector>
using namespace std;

int absDiff(vector<int>& arr1, vector<int>& arr2){
    int sum = 0;
    for(int i=0; i<arr1.size(); i++){
        if(arr1[i] > arr2[i])
            sum += arr1[i] - arr2[i];
