Below is a simple example of how you could create a custom AngularJS filter to sort financial transactions by type and amount. Please note that this is just a basic example and your actual implementation may differ based on the complexity and requirements of your user financial database.

```javascript
var app = angular.module("myApp", []);

app.filter("sortTransactions", function() {
  return function(transactions, type, range) {
    // Filter transactions by type
    if (type) {
      transactions = transactions.filter(function(transaction) {
        return transaction.type === type;
      });
    }

    // Filter transactions by range
    if (range && range.min && range.max) {
      transactions = transactions.filter(function(transaction) {
        return transaction.amount >= range.min && transaction.amount <= range.max;
      });
    }

    // Sort transactions by amount
    transactions.sort(function(a, b) {
      return a.amount - b.amount;
    });

    return transactions;
  };
});
