First, we will create a simple LFU cache class which has `insert`, `get` and `evict` operations.

```python
class LFUCache:

    def __init__(self, capacity):
        self.capacity = capacity
        self.cache = {}
        self.freq_map = {}

    def get(self, key):
        if key in self.cache:
            freq, _ = self.cache[key]
            self.freq_map[freq].remove(key)
            if not self.freq_map[freq]:
                del self.freq_map[freq]
            self.cache[key] = (freq + 1, key)
            self.freq_map.setdefault(freq + 1, set()).add(key)
            return "Success"
        else:
            return "Not found"

    def insert(self, key):
        if key in self.cache:
            self.get(key)
            return

        if len(self.cache) == self.capacity:
            min_freq = min(self.freq_map)
            evict_key = self.freq_map[min_freq].pop()
            if not self.freq_map[min_freq]:
                del self.freq_map[min_freq]
            del self.cache[evict_key]

        self.cache[key] = (1, key)
        self.freq_map.setdefault(1, set()).add(key)

    def evict(self):
        if self.cache:
            min_freq = min(self.freq_map)
            evict_key = self.freq_map[min_freq].pop()
            if not self.freq_map[min_freq]:
                del self.freq_map[min_freq]
            del self.cache[evict_key]
