Here is the implementation of Efficient sorting algorithm in C++:
We are going to use merge sort for our problem, because it's efficient and works in O(n log n) time complexity which is acceptable for sorting.

```cpp
#include<iostream>
#include<vector>
using namespace std;

void merge(vector<int>& arr, int l, int m, int r)
{
    int n1 = m - l + 1;
    int n2 = r - m;

    vector<int> L(n1), R(n2);

    for (int i = 0; i < n1; i++)
        L[i] = arr[l + i];
    for (int j = 0; j < n2; j++)
        R[j] = arr[m + 1 + j];

    int i = 0, j = 0;

    int k = l;
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {
            arr[k] = L[i];
            i++;
        }
        else {
            arr[k] = R[j];
            j++;
        }
        k++;
    }

    while (i < n1) {
        arr[k] = L[i];
        i++;
        k++;
    }

    while (j < n2) {
        arr[k] = R[j];
        j++;
        k++;
    }
}

void mergeSort(vector<int>& arr,int l,int r){
    if(l>=r){
        return;
    }
    int m =l+ (r-l)/2;
    mergeSort(arr,l,m);
    mergeSort(arr,m+1,r);
    merge(arr,l,m,r);
}

int main(){
    vector<int> arr = {4,9,2,6,1,3};
    int arr_size = arr.size();

    mergeSort(arr, 0, arr_size - 1);

    cout << "Sorted array is \n";
    for(int i=0;i<arr_size;i++)
        cout << arr[i] << " ";

    return 0;
}
```

The above code first imports the necessary libraries, then defines the merge() function, which arranges the elements in the correct order. Then it defines mergeSort() function, which recursively divides the array until each sub-array contains a single element, then combines them back in the correct order. The main() function tests the sorting code with the given array of integers.

