In JavaScript, HeapSort can be implemented by building a Max Heap data structure and swapping the root of the Max Heap with the last element, then reducing the heap size. Here is a JavaScript implementation of HeapSort:

```javascript
function heapify(arr, n, i) {
  let largest = i;
  let left = 2 * i + 1;
  let right = 2 * i + 2;

  // If left child is larger than root
  if (left < n && arr[left] > arr[largest])
    largest = left;

  // If right child is larger than largest so far
  if (right < n && arr[right] > arr[largest])
    largest = right;

  // If largest is not root
  if (largest != i) {
    swap(arr, i, largest);

    // Recursively heapify the affected sub-tree
    heapify(arr, n, largest);
  }
}

// Function to swap two elements in the array
function swap(arr, i, j) {
  let temp = arr[i];
  arr[i] = arr[j];
  arr[j] = temp;
}

function heapSort(arr) {
  let n = arr.length;

  // Build heap
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--)
    heapify(arr, n, i);

  // One by one extract an element from heap
  for (let i = n - 1; i >= 0; i--) {
    // Move current root to end
    swap(arr, 0, i);

    // call max heapify on the reduced heap
    heapify(arr, i, 0);
  }
}

// Test the code
let arr = [12, 11, 13, 5, 6, 7];
heapSort(arr);
console.log("Sorted array is", arr);
```
This HeapSort implementation has a time complexity of O(n log n) for all cases (best-case, average-case, and worst-case) as it always requires a full sort.

