```java
import java.util.*;

public class Main{

    public static String replaceWord(String str, String from, String to){
        if(str == null || from == null || to == null || from.isEmpty()){
            throw new IllegalArgumentException("Null or empty String argument");
        }
        return str.replaceAll(from, to);
    }

    public static String reverseWords(String str){
        if(str == null || str.isEmpty()){
            throw new IllegalArgumentException("Null or empty String argument");
        }
        String[] words = str.split(" ");
        String reversedString = "";
        for(String word: words){
            StringBuilder sb = new StringBuilder(word.toLowerCase());
            sb.reverse();

            String reversedWord = sb.toString();
            reversedWord = Character.toUpperCase(reversedWord.charAt(0)) + reversedWord.substring(1);
            reversedString += reversedWord + " ";
        }
        return reversedString.trim();
    }

    public static void main(String[] args){
        String sentence = "Hello world of artificial intelligence";
        System.out.println("Original Sentence: " + sentence);

        String reversedSentence = reverseWords(sentence);
        System.out.println("Reversed Sentence: " + reversedSentence);

        String replacedSentence = replaceWord(reversedSentence, "Olleh", "Hey");
        System.out.println("Replaced Sentence: " + replacedSentence); 
    }
}
