<?php

/** Function to generate all subsets of the given string and check if they
 *  end with the given character
 *  
 *  @param string $string the string to search
 *  @param string $character the character to look for at the end of substrings
 *
 *  @return array $substrings a list of all matching substrings
 */
function getEndingSubstrings($string, $character){
    $substrings = array();

    // Get the length of the string
    $len = strlen($string);

    // Generate all substrings
    for($length = 1; $length <= $len; $length++){
        for($i = 0; $i <= $len - $length; $i++){
            $substring = substr($string, $i, $length);

            // Check if the substring ends with the specified character
            if(substr($substring, -1) === $character){
                $substrings[] = $substring;
            }
        }
    }

    return $substrings;
}

// Example usage
$string = 'Hello, Brave New World!';
$character = 'o';

$substrings = getEndingSubstrings($string, $character);

echo "Substrings of '{$string}' that end with '{$character}':\n";

foreach($substrings as $substring){
    echo "'{$substring}', ";
}

echo "\n";

// Check if original string ends with given character
if(substr($string, -1) === $character){
    echo "The original string '{$string}' ends with character '{$character}'.";
} else {
    echo "The original string '{$string}' does not end with character '{$character}'.";
}

?>
```

