def factorial_with_product(n):
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    elif type(n) is not int:
        raise TypeError("n must be an integer")

    product = 1
    factorial = 1
    j = n
    while True:
        if n > 1:
            factorial = factorial * n
            n = n - 1
        if j > 1:
            if j % 3 == 0:
