```python
def highest_prime(n, i = 2): 
    if n <= 2:
        if n == 2: 
            return n
        else: 
            return -1

    if n % i == 0: 
        n = n / i 
        if n == 1: 
            return i 
        else: 
            return highest_prime(n, i) 
    else: 
        return highest_prime(n, i + 1)   


numeral = 105 # Any given predetermined numeral
