```python
from collections import Counter
import os

def read_input():
    while True:
        source_type = input("Read from string (1) or file (2)? ")
        if source_type == '1':
            text = input("Enter the string: ")
            return Counter(char.lower() for char in text if char.isalnum()), None
        elif source_type == '2':
            filename = input("Enter the filename: ")
            if os.path.isfile(filename):
                with open(filename) as file:
                    lines = file.readlines()
                    text = ''.join(lines)
                    return Counter(char.lower() for char in text if char.isalnum()), lines
            else:
                print("File not found. Try again.")
        else:
            print("Invalid option. Try again.")

def find_least_common(counter, lines):
    min_count = min(counter.values())
    least_common_chars = [char for char, count in counter.items() if count == min_count]
    min_ascii = min(least_common_chars, key=ord)
    if lines is not None:
        for i, line in enumerate(lines):
            if min_ascii in line.lower():
                return min_ascii, i + 1
    return min_ascii, None

def main():
    try:
        counter, lines = read_input()
        char, line = find_least_common(counter, lines)
        print(f"The least common character is '{char}'.")
        if line is not None:
            print(f"It first appears on line {line}.")
    except Exception as e:
        print(f"Error: {str(e)}")

if __name__ == "__main__":
    main()
```
