    }
});

app.delete('/logout', (req, res) => {
    req.session.destroy();
    res.json({ success: true });
});

//Middleware to cache responses
app.use((req, res, next) => {
    let key = req.url;
    if (cache[key]) {
        res.send(cache[key]);
    } else {
        res.sendResponse = res.send;
        res.send = (body) => {
            cache[key] = body;
            res.sendResponse(body);
        }
        next();
    }
});

app.listen(3000, () => {
