To solve the problem, we first create the service component and "about us" component. 

1. Let's start with the generation of our service and our component:

    ```
    ng generate service aboutService
    ng generate component aboutUs
    ```

2. Update the `about.service.ts` file. We make use of Angular’s HttpClient module to make HTTP requests:

    ```typescript
    //about.service.ts
    import { Injectable } from '@angular/core';
    import { HttpClient } from '@angular/common/http';
    import { Observable } from 'rxjs';

    @Injectable({
       providedIn: 'root'
    })
    export class AboutService {
       private url = 'http://externalapi.com/aboutus';

       constructor(private http: HttpClient) { }

       getAboutUsContent(): Observable<any> {
           return this.http.get<any>(this.url);
       }
    } 
    ```

3. Update the `about-us.component.ts` file:

    ```typescript
    // about-us.component.ts
    import { Component, OnInit } from '@angular/core';
    import { AboutService } from '../services/about.service';

    @Component({
      selector: 'app-about-us',
      template: '<div [innerHTML]="aboutUsContent"></div>',
      styleUrls: ['./about-us.component.css']
    })
    export class AboutUsComponent implements OnInit {
      aboutUsContent: any;

      constructor(private aboutService: AboutService) { 
        setInterval(() => { 
          this.getAboutUsContent(); 
        }, 5000); // Update every 5 seconds
      }

      ngOnInit(): void {
        this.getAboutUsContent();
      }

      getAboutUsContent(): void {
        this.aboutService.getAboutUsContent()
          .subscribe(content => {
            this.aboutUsContent = content;
          });
      }
    }
    ```
Here, we use `setInterval()` to periodically fetch about us content every 5 seconds. 

