Here's a simple program in Objective-C to sort an array of integers using bubble sort:

```Objective-C
#import <Foundation/Foundation.h>

@interface BubbleSort : NSObject
- (NSArray *)sortArray:(NSArray *)array;
@end

@implementation BubbleSort

- (NSArray *)sortArray:(NSArray *)array {
    NSMutableArray *mutableArray = [NSMutableArray arrayWithArray:array];

    for(int i = 0; i < [mutableArray count] - 1; i++) {
        for (int j = 0; j < [mutableArray count] - i - 1; j++) {
            if ([mutableArray[j] intValue] > [mutableArray[j+1] intValue]) {
                [mutableArray exchangeObjectAtIndex:j withObjectAtIndex:(j + 1)];
            }
        }
    }

    return [NSArray arrayWithArray:mutableArray];
}

@end

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        BubbleSort *bubbleSort = [BubbleSort new];
        NSLog(@"%@", [bubbleSort sortArray:@[@7, @5, @2, @4, @3, @9]]);
    }
    return 0;
}
```
This code defines a BubbleSort class with a sortArray: method, which sorts an NSArray of numbers in ascending order using the bubble sort algorithm. The main function creates a new BubbleSort instance and uses it to sort the array {7, 5, 2, 4, 3, 9}. The sorted array is then logged to the console.

