```TypeScript
import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, throwError } from 'rxjs';
import { catchError } from 'rxjs/operators';

@Injectable({
  providedIn: 'root'
})
export class DataService {

  private API_URL = 'http://www.example.com/api/v1/data';

  constructor(private http: HttpClient) { }

  fetchGrid(): Observable<any> {
    return this.http.get(this.API_URL).pipe(catchError(this.handleError));
  }

  handleError(error) {
    let errorMessage = '';
    if (error.error instanceof ErrorEvent) {
        errorMessage = `Error: ${error.error.message}`;
    } else {
        errorMessage = `Error Code: ${error.status}\nMessage: ${error.message}`;
    }
    return throwError(errorMessage);
  }
}

// processGrid.service.ts
import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class ProcessGridService {

  constructor() { }

  getUniquePaths(grid, m, n): void {
    let result = [];
    this.findPaths(grid, m, n, 0, 0, "", result);

    for(let i in result) {
      console.log(result[i]);
    }
  }

  findPaths(grid, m, n, i, j, path, result) {
    path += `(${i},${j}) `;

    if(i==m-1 && j==n-1) {
      result.push(path);
      return;
    }

    if(i+1<m) {
      this.findPaths(grid, m, n, i+1, j, path, result);
    }

    if(j+1<n) {
      this.findPaths(grid, m, n, i, j+1, path, result);
    }

    if(i+1<m && j+1<n) {
      this.findPaths(grid, m, n, i+1, j+1, path, result);
    }
  }
}
```

