```java
public class Sphere {

  private double radius;
  private String color;
  private double transparency;

  public Sphere(double radius, String color, double transparency) {
    this.radius = radius;
    this.color = color;
    this.transparency = transparency;
  }

  public double calculateVolume() {
    return 4/3 * Math.PI * Math.pow(this.radius, 3);
  }

  public double calculateSurfaceArea() {
    return 4 * Math.PI * Math.pow(this.radius, 2);
  }

  public void setColor(String newColor) {
    this.color = newColor;
  }

  public void setTransparency(double newTransparency) {
    this.transparency = newTransparency;
  }

  public double getRadius() {
    return this.radius;
  }

  public String getColor() {
    return this.color;
  }

  public double getTransparency() {
   return this.transparency;
  }

  public void printDetails() {
    System.out.println("Details of the Sphere");
    System.out.println("Radius : " + getRadius());
    System.out.println("Color : " + getColor());
    System.out.println("Transparency : " + getTransparency());
    System.out.println("Volume : " + calculateVolume());
    System.out.println("Surface Area : " + calculateSurfaceArea());
  }
}

public class TestSphere {

  public static void main(String[] args) {

    Sphere sphereObject = new Sphere(5, "Red", 0.5);
    sphereObject.printDetails();
    sphereObject.setColor("Yellow");
    sphereObject.setTransparency(0.9);
    System.out.println("After changing color and transparency...");
    sphereObject.printDetails();
  }
}

```

The above code creates a class "Sphere", with radius, color and transparency as instance variables. It provides methods to calculateVolume and calculateSurfaceArea and methods to set the color and transparency (setColor and setTransparency).

