function findLeastFrequentChar(str) {
    let charMap = new Map();

    // populate charMap with frequency counts
    for(let char of str) {
        if (charMap.has(char))
            charMap.set(char, charMap.get(char) + 1);
        else
            charMap.set(char, 1);
    }

    // find and return the least frequent character
    let minFrequency = Infinity;
    let leastFrequentChar = null;
    for(let [char, frequency] of charMap) {
        if(frequency < minFrequency){
            minFrequency = frequency;
            leastFrequentChar = char;
        }
    }
    return leastFrequentChar;
}

